#!/usr/bin/env python3
"""A small, self-contained terminal Git history browser."""
import os
import sys
import re
import math
import time
import signal
import select
import termios
import tty
import subprocess
import datetime
import unicodedata
import threading
from dataclasses import dataclass, field

DEFAULT = (-1, -1, 0)
PALETTE = [12, 2, 5, 6, 3, 1, 4, 13, 10, 14, 11, 9]
EMPTY_TREE = '4b825dc642cb6eb9a060e54bf8d69288fbee4904'


def style(fg=-1, bg=-1, bold=False, underline=False):
    return (fg, bg, int(bold) | (2 if underline else 0))


def charwidth(c):
    if unicodedata.combining(c) or c in ('\u200d', '\ufe0f', '\ufe0e'):
        return 0
    if ord(c) < 32 or 0x7f <= ord(c) < 0xa0:
        return 0
    return 2 if unicodedata.east_asian_width(c) in ('W', 'F') else 1


def width(s):
    return sum(charwidth(c) for c in s)


def clip(s, n):
    out = ''
    pos = 0
    for c in s:
        w = charwidth(c)
        if pos + w > n:
            break
        if w or pos:
            out += c
        pos += w
    return out


def rnd(n):
    return int(math.floor(n + .5))


class Screen:
    def __init__(self, w, h):
        self.w, self.h = w, h
        self.cells = [[(' ', DEFAULT) for _ in range(w)] for _ in range(h)]

    def fill(self, x, y, w, h, st=DEFAULT):
        for j in range(max(0, y), min(self.h, y + h)):
            for i in range(max(0, x), min(self.w, x + w)):
                self.cells[j][i] = (' ', st)

    def text(self, x, y, s, st=DEFAULT, limit=None):
        if not 0 <= y < self.h:
            return x
        right = self.w if limit is None else min(self.w, x + max(0, limit))
        for c in s:
            cw = charwidth(c)
            if cw == 0:
                if 0 < x <= self.w and c not in '\n\r\t':
                    oc, ost = self.cells[y][x - 1]
                    self.cells[y][x - 1] = (oc + c, ost)
                continue
            if x + cw > right:
                break
            if x >= 0:
                self.cells[y][x] = (c, st)
                if cw == 2 and x + 1 < self.w:
                    self.cells[y][x + 1] = ('', st)
            x += cw
        return x

    def spans(self, x, y, spans, limit):
        end = x + max(0, limit)
        for s, st in spans:
            if x >= end:
                break
            x = self.text(x, y, s, st, end - x)
        return x

    def box(self, x, y, w, h, title, color=8, bg=-1):
        if w <= 0 or h <= 0:
            return
        st = style(color, bg)
        if w == 1:
            for j in range(y, y + h):
                self.text(x, j, '│', st)
            return
        self.text(x, y, '┌' + '─' * (w - 2) + '┐', st)
        if h > 1:
            self.text(x, y + h - 1, '└' + '─' * (w - 2) + '┘', st)
        for j in range(y + 1, y + h - 1):
            self.text(x, j, '│', st)
            self.text(x + w - 1, j, '│', st)
        self.text(x + 1, y, ' ' + title + ' ', st, w - 2)

    def output(self):
        parts = []
        last = None
        for y, row in enumerate(self.cells):
            parts.append('\x1b[%d;1H' % (y + 1))
            for c, st in row:
                if not c:
                    continue
                if st != last:
                    fg, bg, effects = st
                    codes = ['0']
                    if fg >= 0:
                        codes += ['38', '5', str(fg)]
                    if bg >= 0:
                        codes += ['48', '5', str(bg)]
                    if effects & 1:
                        codes.append('1')
                    if effects & 2:
                        codes.append('4')
                    parts.append('\x1b[' + ';'.join(codes) + 'm')
                    last = st
                parts.append(c)
        parts.append('\x1b[0m')
        return ''.join(parts)


def wrap_spans(spans, n):
    """Word wrapping retaining styles and explicit spaces inside a line."""
    if n < 1:
        return [[]]
    chars = []
    for text, st in spans:
        chars += [(c, st) for c in text]
    if not chars:
        return [[]]
    tokens = []
    i = 0
    while i < len(chars):
        white = chars[i][0].isspace()
        j = i + 1
        while j < len(chars) and chars[j][0].isspace() == white:
            j += 1
        tokens.append((white, chars[i:j]))
        i = j
    lines, line = [], []
    used = 0
    pending = []
    for white, tok in tokens:
        if white:
            pending += tok
            continue
        tw = sum(charwidth(c) for c, _ in tok)
        pw = sum(charwidth(c) for c, _ in pending)
        if line and used + pw + tw > n:
            lines.append(line)
            line, used, pending = [], 0, []
        if line:
            for c, st in pending:
                if used + charwidth(c) <= n:
                    line.append((c, st)); used += charwidth(c)
        pending = []
        for c, st in tok:
            cw = charwidth(c)
            if used + cw > n and line:
                lines.append(line); line, used = [], 0
            if cw <= n:
                line.append((c, st)); used += cw
    if line or not lines:
        lines.append(line)
    result = []
    for ln in lines:
        segments = []
        for c, st in ln:
            if segments and segments[-1][1] == st:
                segments[-1] = (segments[-1][0] + c, st)
            else:
                segments.append((c, st))
        result.append(segments)
    return result


@dataclass
class Branch:
    name: str
    oid: str
    remote: bool = False
    paired: bool = False


@dataclass
class Commit:
    oid: str
    parents: list
    stamp: int
    author: str
    email: str
    message: str
    branches: list = field(default_factory=list)
    color: int = 12
    col: int = 0

    @property
    def subject(self):
        para = self.message.split('\n\n', 1)[0]
        return ' '.join(para.split())

    @property
    def date(self):
        try:
            return datetime.datetime.utcfromtimestamp(self.stamp).strftime('%Y-%m-%d %H:%M:%S')
        except (ValueError, OverflowError, OSError):
            return ''


class Repository:
    def __init__(self):
        self.cwd = os.getcwd()
        p = self.git('rev-parse', '--absolute-git-dir')
        if p.returncode:
            raise ValueError('not a repository')
        self.gitdir = p.stdout.decode(errors='replace').strip()
        top = self.git('rev-parse', '--show-toplevel')
        self.root = top.stdout.decode(errors='replace').strip() if top.returncode == 0 else self.gitdir
        self.name = os.path.basename(self.root.rstrip('/')) or self.root
        self.cache = {}
        self.commits = []
        self.branches = []
        self.head = ''
        self.head_name = ''
        self.dirty = None
        self.load()

    def git(self, *args):
        try:
            return subprocess.run(['git', '-c', 'core.quotepath=false', *args], cwd=self.cwd,
                                  stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        except OSError as e:
            return subprocess.CompletedProcess(args, 1, b'', str(e).encode())

    def text(self, *args):
        return self.git(*args).stdout.decode('utf-8', errors='replace').strip()

    def diff(self, args):
        ns = self.git('diff', '--no-ext-diff', '--no-renames', '--name-status', '-z', *args).stdout
        fields = ns.decode(errors='replace').split('\0')
        statuses = {}
        for i in range(0, len(fields) - 1, 2):
            if fields[i]:
                statuses[fields[i + 1]] = fields[i][0]
        stat = self.git('diff', '--no-ext-diff', '--no-renames', '--numstat', '-z', *args).stdout
        files = []
        total_a = total_d = 0
        for record in stat.decode(errors='replace').split('\0'):
            vals = record.split('\t', 2)
            if len(vals) != 3:
                continue
            a, d, path = vals
            binary = (a == '-' or d == '-')
            a = int(a) if a.isdigit() else 0
            d = int(d) if d.isdigit() else 0
            total_a += a; total_d += d
            files.append((path, statuses.get(path, 'M'), a, d, binary))
        return files, total_a, total_d

    def load(self):
        self.head = self.text('rev-parse', '--verify', 'HEAD')
        if len(self.head) != 40:
            self.head = ''
        self.head_name = self.text('symbolic-ref', '--quiet', '--short', 'HEAD') if self.head else ''
        if self.head and not self.head_name:
            self.head_name = 'HEAD'
        refs = self.git('for-each-ref', '--format=%(refname)%00%(objectname)%00%(symref)',
                        'refs/heads/', 'refs/remotes/').stdout.decode(errors='replace')
        bs = []
        oids = []
        for line in refs.splitlines():
            f = line.split('\0')
            if len(f) < 3 or f[2] or f[0].endswith('/HEAD'):
                continue
            ref, oid = f[:2]
            remote = ref.startswith('refs/remotes/')
            name = ref[len('refs/remotes/') if remote else len('refs/heads/'):]
            bs.append(Branch(name, oid, remote))
            oids.append(oid)
        lookup = {(b.name, b.oid): b for b in bs if b.remote}
        paired = set()
        for b in bs:
            if not b.remote and ('origin/' + b.name, b.oid) in lookup:
                b.paired = True
                paired.add(('origin/' + b.name, b.oid))
        self.branches = [b for b in bs if not (b.remote and (b.name, b.oid) in paired)]
        self.branches.sort(key=lambda b: (b.name != self.head_name, b.remote, b.name))
        if self.head:
            oids.append(self.head)
        oids = list(dict.fromkeys(oids))
        self.commits = []
        if oids:
            raw = self.git('log', '--no-show-signature', '--date-order', '--max-count=500',
                           '--format=%H%x00%P%x00%ct%x00%an%x00%ae%x00%B%x00%x1e', *oids).stdout
            for block in raw.decode('utf-8', errors='replace').split('\x1e'):
                f = block.lstrip('\n').split('\0')
                if len(f) < 7:
                    continue
                try:
                    c = Commit(f[0], f[1].split(), int(f[2]), f[3], f[4], f[5].rstrip('\n'))
                except ValueError:
                    continue
                c.branches = [b for b in self.branches if b.oid == c.oid]
                self.commits.append(c)
        staged = self.diff(['--cached'])
        unstaged = self.diff([])
        paths = set()
        dirty_files = []
        for f in staged[0] + unstaged[0]:
            if f[0] not in paths:
                paths.add(f[0]); dirty_files.append(f)
        self.dirty = (dirty_files, staged[1] + unstaged[1], staged[2] + unstaged[2]) if dirty_files else None

    def stats(self, c):
        if c is None:
            return self.dirty or ([], 0, 0)
        if c.oid not in self.cache:
            self.cache[c.oid] = self.diff([c.parents[0] if c.parents else EMPTY_TREE, c.oid])
        return self.cache[c.oid]


def graph_layout(commits):
    lanes = []
    rows = []
    maxcols = 1
    for ci, c in enumerate(commits):
        try:
            col = lanes.index(c.oid)
        except ValueError:
            if None in lanes:
                col = lanes.index(None); lanes[col] = c.oid
            else:
                col = len(lanes); lanes.append(c.oid)
        c.col, c.color = col, PALETTE[col % len(PALETTE)]
        before = list(lanes)
        graph = {}
        for i, v in enumerate(lanes):
            if v:
                graph[2 * i] = ('│', PALETTE[i % len(PALETTE)])
        graph[2 * col] = ('●', c.color)
        joins = []
        if not c.parents:
            lanes[col] = None
        else:
            first = c.parents[0]
            if first in lanes and lanes.index(first) != col:
                joins.append((col, lanes.index(first)))
                lanes[col] = None
            else:
                lanes[col] = first
            for par in c.parents[1:]:
                if par in lanes:
                    pcol = lanes.index(par)
                else:
                    free = [i for i, v in enumerate(lanes) if v is None and i != col]
                    if free:
                        pcol = free[0]; lanes[pcol] = par
                    else:
                        pcol = len(lanes); lanes.append(par)
                if pcol == col:
                    continue
                color = PALETTE[pcol % len(PALETTE)]
                lo, hi = sorted((col * 2, pcol * 2))
                for x in range(lo + 1, hi):
                    if x in graph and graph[x][0] == '│':
                        graph[x] = ('┼', graph[x][1])
                    else:
                        graph[x] = ('─', color)
                graph[pcol * 2] = ('╮' if pcol > col else '╭', color)
        rows.append({'commit': ci, 'graph': graph})
        maxcols = max(maxcols, len(lanes), len(before))
        for src, dest in joins:
            gr = {i * 2: ('│', PALETTE[i % len(PALETTE)]) for i, v in enumerate(lanes) if v}
            lo, hi = sorted((src * 2, dest * 2))
            for x in range(lo + 1, hi):
                gr[x] = ('┼', gr[x][1]) if x in gr else ('─', PALETTE[src % len(PALETTE)])
            gr[src * 2] = ('╯' if src > dest else '╰', PALETTE[src % len(PALETTE)])
            gr[dest * 2] = ('├' if dest < src else '┤', PALETTE[dest % len(PALETTE)])
            rows.append({'commit': None, 'graph': gr})
        while lanes and lanes[-1] is None:
            lanes.pop()
    return rows, maxcols


