def fuzzy(pattern, text):
    pat, txt = pattern.lower(), text.lower()
    if not pat:
        return None
    positions = []
    pos = 0
    for c in pat:
        at = txt.find(c, pos)
        if at < 0:
            return None
        positions.append(at); pos = at + 1
    score = 100 * len(pat) - len(txt)
    score -= positions[0] * 3
    for i, pos in enumerate(positions):
        if pos == 0:
            score += 40
        elif text[pos - 1] in '/_- .':
            score += 35
        elif text[pos].isupper() and text[pos - 1].islower():
            score += 25
        if i and pos == positions[i - 1] + 1:
            score += 30
        elif i:
            score -= pos - positions[i - 1] - 1
    return score, positions


def config():
    cfg = dict(auto_refresh=True, refresh_interval=10, auto_fetch=True, fetch_interval=60)
    base = os.environ.get('XDG_CONFIG_HOME') or os.path.join(os.path.expanduser('~'), '.config')
    try:
        data = open(os.path.join(base, 'keifu', 'config.toml'), encoding='utf-8').read()
        section = ''
        vals = {}
        for line in data.splitlines():
            line = line.split('#')[0].strip()
            if not line:
                continue
            if line.startswith('[') and line.endswith(']'):
                section = line[1:-1].strip(); continue
            if '=' not in line:
                return cfg
            k, v = (part.strip() for part in line.split('=', 1))
            if section == 'refresh' and k in cfg:
                if k.startswith('auto_'):
                    if v not in ('true', 'false'):
                        return cfg
                    vals[k] = v == 'true'
                else:
                    if not re.fullmatch(r'\+?[0-9][0-9_]*', v):
                        return cfg
                    vals[k] = int(v.replace('_', ''))
        cfg.update(vals)
    except (OSError, ValueError):
        pass
    cfg['refresh_interval'] = max(1, cfg['refresh_interval'])
    cfg['fetch_interval'] = max(10, cfg['fetch_interval'])
    return cfg


class App:
    def __init__(self, repo):
        self.repo = repo
        self.selected = 0
        self.branch_index = 0
        self.offset = 0
        self.mode = 'normal'
        self.input = ''
        self.error = ''
        self.pending_delete = None
        self.search_results = []
        self.search_choice = 0
        self.search_offset = 0
        self.search_saved = (0, 0, 0)
        self.quit = False
        self.w, self.h = 80, 24
        self.config = config()
        self.last_refresh = self.last_fetch = time.monotonic()
        self.fetching = False
        self.fetch_result = None
        self.rebuild()

    def rebuild(self):
        r = self.repo
        self.items = ([None] if r.dirty else []) + r.commits
        self.rows, self.cols = graph_layout(r.commits)
        if r.dirty:
            head_ci = next((i for i, c in enumerate(r.commits) if c.oid == r.head), -1)
            head_row = next((i for i, row in enumerate(self.rows) if row['commit'] == head_ci), -1)
            if head_row == 0:
                col = r.commits[head_ci].col
            else:
                occupied = set()
                for row in self.rows[:max(0, head_row)]:
                    occupied.update(x // 2 for x in row['graph'] if x % 2 == 0)
                col = 0
                while col in occupied:
                    col += 1
            for i, row in enumerate(self.rows):
                if i < head_row:
                    row['graph'][col * 2] = ('│', 3)
                elif i == head_row:
                    dest = r.commits[head_ci].col
                    if col != dest:
                        lo, hi = sorted((dest * 2, col * 2))
                        for x in range(lo + 1, hi):
                            row['graph'][x] = ('┼', row['graph'][x][1]) if x in row['graph'] and row['graph'][x][0] == '│' else ('─', 3)
                        row['graph'][col * 2] = ('╯' if col > dest else '╰', 3)
                if row['commit'] is not None:
                    row['commit'] += 1
            self.rows.insert(0, {'commit': 0, 'graph': {2 * col: ('●', 3)}})
            self.cols = max(self.cols, col + 1)
        self.selected = max(0, min(self.selected, len(self.items) - 1))
        self.branch_index = min(self.branch_index, max(0, len(self.current_branches()) - 1))

    def current(self):
        return self.items[self.selected] if self.items else None

    def current_branches(self):
        c = self.current()
        return c.branches if c else []

    def current_branch(self):
        bs = self.current_branches()
        return bs[self.branch_index % len(bs)] if bs else None

    def refresh(self):
        c = self.current()
        old = c.oid if c else None
        b = self.current_branch()
        bname = b.name if b else ''
        self.repo.load()
        self.rebuild()
        self.selected = next((i for i, c in enumerate(self.items) if (c.oid if c else None) == old), 0)
        self.branch_index = next((i for i, b in enumerate(self.current_branches()) if b.name == bname), 0)
        self.last_refresh = time.monotonic()

    def navigate(self, n):
        self.selected = max(0, min(len(self.items) - 1, n))
        self.branch_index = 0

    def fail(self, s):
        self.mode = 'error'
        self.error = s

    def fetch(self, manual=True):
        if self.fetching:
            return
        self.fetching = True
        self.last_fetch = time.monotonic()
        def work():
            p = self.repo.git('fetch', 'origin')
            self.fetch_result = (p, manual)
        threading.Thread(target=work, daemon=True).start()

    def checkout(self):
        c = self.current()
        if c is None:
            return
        b = self.current_branch()
        if b:
            target = b.name
            if b.remote and b.name.startswith('origin/'):
                name = b.name[len('origin/'):]
                exists = bool(self.repo.text('show-ref', '--verify', '--hash', 'refs/heads/' + name))
                p = self.repo.git('checkout', '-q', '-B', name, 'refs/remotes/' + b.name)
                if p.returncode == 0 and not exists:
                    self.repo.git('branch', '--set-upstream-to=' + b.name, name)
            elif b.remote:
                p = self.repo.git('checkout', '-q', '--detach', 'refs/remotes/' + b.name)
            else:
                p = self.repo.git('checkout', '-q', b.name)
        else:
            target = c.oid[:7]
            p = self.repo.git('checkout', '-q', '--detach', c.oid)
        if p.returncode:
            self.fail("Failed to checkout '%s'" % target)
        else:
            self.refresh()

    def update_search(self):
        found = []
        for ci, c in enumerate(self.items):
            if c:
                for bi, b in enumerate(c.branches):
                    f = fuzzy(self.input, b.name)
                    if f:
                        found.append((f[0], ci, bi, b, f[1]))
        found.sort(key=lambda item: -item[0])
        self.search_results = found
        self.search_choice = self.search_offset = 0
        self.search_jump()

    def search_jump(self):
        if self.search_results:
            choice = self.search_results[self.search_choice]
            self.selected, self.branch_index = choice[1:3]

    def key(self, key):
        if self.mode == 'help':
            if key in ('?', 'q', 'esc'):
                self.mode = 'normal'
            return
        if self.mode == 'error':
            if key in ('esc', 'enter'):
                self.mode = 'normal'
            return
        if self.mode == 'confirm':
            if key in ('y', 'Y', 'enter'):
                b = self.pending_delete
                self.mode = 'normal'
                p = self.repo.git('branch', '-D', b.name)
                if p.returncode:
                    self.fail("Failed to delete branch '%s'" % b.name)
                else:
                    self.refresh()
            elif key in ('n', 'N', 'esc'):
                self.mode = 'normal'
            return
        if self.mode in ('branch', 'search'):
            search_mode = self.mode == 'search'
            if key == 'esc' or (search_mode and key == 'backspace' and not self.input):
                if search_mode:
                    self.selected, self.branch_index, self.offset = self.search_saved
                self.mode = 'normal'
            elif key == 'enter':
                if search_mode:
                    self.mode = 'normal'
                else:
                    name = self.input.strip()
                    self.mode = 'normal'
                    c = self.current()
                    if name and c:
                        p = self.repo.git('branch', '--', name, c.oid)
                        if p.returncode:
                            self.fail("Failed to create branch '%s'" % name)
                        else:
                            self.refresh()
            elif search_mode and key in ('up', 'ctrl-k', 'down', 'ctrl-j'):
                if self.search_results:
                    step = -1 if key in ('up', 'ctrl-k') else 1
                    self.search_choice = max(0, min(len(self.search_results) - 1, self.search_choice + step))
                    self.search_jump()
            elif key == 'backspace':
                self.input = self.input[:-1]
                if search_mode:
                    self.update_search()
            elif len(key) == 1 and ord(key) >= 32:
                self.input += key
                if search_mode:
                    self.update_search()
            return
        if key in ('q', 'esc'):
            self.quit = True
        elif key in ('j', 'down'):
            self.navigate(self.selected + 1)
        elif key in ('k', 'up'):
            self.navigate(self.selected - 1)
        elif key in ('g', 'home'):
            self.navigate(0)
        elif key in ('G', 'end'):
            self.navigate(len(self.items) - 1)
        elif key == 'ctrl-d':
            self.navigate(self.selected + 10)
        elif key == 'ctrl-u':
            self.navigate(self.selected - 10)
        elif key in ('h', 'left', 'l', 'right'):
            bs = self.current_branches()
            if bs:
                self.branch_index = (self.branch_index + (-1 if key in ('h', 'left') else 1)) % len(bs)
        elif key in (']', 'tab'):
            targets = [i for i, c in enumerate(self.items) if c and c.branches and i > self.selected]
            self.navigate(targets[0] if targets else 0)
        elif key in ('[', 'backtab'):
            targets = [i for i, c in enumerate(self.items) if c and c.branches and i < self.selected]
            if targets:
                self.navigate(targets[-1])
        elif key == '@':
            target = next((i for i, c in enumerate(self.items) if c and c.oid == self.repo.head), None)
            if target is not None:
                self.navigate(target)
        elif key == '?':
            self.mode = 'help'
        elif key == '/':
            self.mode = 'search'
            self.input = ''
            self.search_saved = (self.selected, self.branch_index, self.offset)
            self.search_results = []
            self.search_choice = self.search_offset = 0
        elif key == 'b':
            self.mode = 'branch'
            self.input = ''
        elif key == 'd':
            b = self.current_branch()
            if b and not b.remote and b.name != self.repo.head_name:
                self.pending_delete = b
                self.mode = 'confirm'
        elif key == 'enter':
            self.checkout()
        elif key == 'R':
            self.refresh()
        elif key == 'f':
            self.fetch()

    def centered(self, pw, ph):
        x = rnd(self.w * (100 - pw) / 200)
        x2 = rnd(self.w * (100 + pw) / 200)
        y = rnd(self.h * (100 - ph) / 200)
        y2 = rnd(self.h * (100 + ph) / 200)
        return x, y, x2 - x, y2 - y

    def render_list(self, s, height):
        s.box(0, 0, self.w, height, 'Commits')
        view = max(0, height - 2)
        pos = next((i for i, r in enumerate(self.rows) if r['commit'] == self.selected), 0)
        if pos < self.offset:
            self.offset = pos
        elif pos >= self.offset + view:
            self.offset = max(0, pos - view + 1)
        self.offset = min(self.offset, max(0, len(self.rows) - view))
        text_x = self.cols * 2 + 3
        available = max(0, self.w - text_x - 2)
        author = available >= 60
        date = available >= 71
        short = available >= 80
        metadata = (10 if author else 0) + (12 if date else 0) + (9 if short else 0)
        text_w = max(0, available - metadata)
        for y, row in enumerate(self.rows[self.offset:self.offset + view], 1):
            ci = row['commit']
            selected = ci is not None and ci == self.selected
            bg = 8 if selected else -1
            if selected:
                s.fill(1, y, self.w - 2, 1, style(-1, bg, True))
            c = self.items[ci] if ci is not None else None
            for x, (glyph, color) in row['graph'].items():
                if glyph == '●' and ci is not None and c and c.oid == self.repo.head and self.repo.head_name != 'HEAD':
                    glyph = '◉'
                s.text(2 + x, y, glyph, style(color, bg, True), max(0, self.w - 3 - x))
            if ci is None:
                continue
            if c is None:
                s.text(text_x, y, 'uncommitted changes (%d)' % len(self.repo.dirty[0]),
                       style(3, bg, selected), max(0, self.w - text_x - 2))
                continue
            spans = []
            if c.branches:
                bi = self.branch_index if selected else 0
                b = c.branches[bi % len(c.branches)]
                label = '[' + b.name + (' ↔ origin' if b.paired and len(c.branches) == 1 else '') + ']'
                if len(c.branches) > 1:
                    label += ' +%d' % (len(c.branches) - 1)
                spans.append((label, style(0 if selected else c.color, bg, True)))
                spans.append((' ', style(-1, bg, selected)))
            spans.append((c.subject, style(-1, bg, selected)))
            s.spans(text_x, y, spans, text_w)
            x = self.w - 2 - metadata
            if date:
                s.text(x + 2, y, c.date[:10], style(8, bg, selected)); x += 12
            if author:
                name = clip(c.author, 8)
                name += ' ' * (8 - width(name))
                s.text(x + 2, y, name, style(6, bg, selected)); x += 10
            if short:
                s.text(x + 2, y, c.oid[:7], style(3, bg, selected))
        return pos - self.offset + 1

    def render_detail(self, s, x, y, w, h):
        s.box(x, y, w, h, 'Commit Detail')
        if w < 3 or h < 3:
            return
        lines = []
        c = self.current()
        if not self.items:
            lines = [[('Select a commit', style(8))]]
        elif c is None:
            lines = [[('Uncommitted Changes', style(-1, -1, True))], [],
                     [('%d files with changes' % len(self.repo.dirty[0]), DEFAULT)]]
        else:
            b = style(-1, -1, True)
            lines = [[('Commit: ', b), (c.oid, style(3))],
                     [('Author: ', b), (c.author + ' <' + c.email + '>', style(4))],
                     [('Date:   ', b), (c.date, style(8))]]
            if c.parents:
                lines.append([('Parent: ', b), (', '.join(p[:7] for p in c.parents), style(8))])
            lines.append([])
            lines.extend([[(line, DEFAULT)] for line in c.message.split('\n')])
        output = []
        for line in lines:
            output += wrap_spans(line, w - 2)
        for i, spans in enumerate(output[:h - 2]):
            s.spans(x + 1, y + 1 + i, spans, w - 2)

    def render_files(self, s, x, y, w, h):
        s.box(x, y, w, h, 'Changed Files')
        if not self.items or w < 3 or h < 3:
            return
        files, a, d = self.repo.stats(self.current())
        lines = [[('%d files changed' % len(files), style(-1, -1, True)), ('  ', DEFAULT),
                  ('+%d' % a, style(2)), (' ', DEFAULT), ('-%d' % d, style(1))], []]
        for path, status, a, d, binary in files[:50]:
            col = {'A': 2, 'D': 1, 'M': 3, 'R': 6, 'T': 5, 'U': 1}.get(status, 8)
            spans = [(' ' + status + ' ', style(col)), (path, DEFAULT)]
            if a or d:
                spans += [(' ', DEFAULT), ('+%d' % a, style(2)), (' ', DEFAULT), ('-%d' % d, style(1))]
            lines.append(spans)
        for i, spans in enumerate(lines[:h - 2]):
            s.spans(x + 1, y + 1 + i, spans, w - 2)

    def render_footer(self, s):
        spans = [(' ' + self.repo.name + ' ', style(0, 5, True)), (' ', DEFAULT)]
        if self.repo.head_name:
            spans.extend([(' ' + self.repo.head_name + ' ', style(0, 2)), (' ', DEFAULT)])
        tag = {'help': 'HELP', 'branch': 'INPUT', 'search': 'INPUT', 'confirm': 'CONFIRM', 'error': 'ERROR'}.get(self.mode, '')
        if self.mode == 'help':
            hints = [('Esc/q', 'close help')]
        elif self.mode in ('branch', 'search'):
            hints = [('Enter', 'confirm'), ('Esc', 'cancel')]
        elif self.mode == 'confirm':
            hints = [('y', 'yes'), ('n', 'no')]
        elif self.mode == 'error':
            msg = self.error.splitlines()[0]
            spans += [(' ' + msg + ' ', style(15, 1, True)), ('  ', DEFAULT)]
            hints = [('Esc/Enter', 'close')]
        elif self.fetching:
            hints = []
            spans.append((' Fetching from origin...', style(3)))
        else:
            hints = [('j/k', 'move'), ('Enter', 'checkout'), ('b', 'branch'), ('f', 'fetch'), ('?', 'help'), ('q', 'quit')]
        for i, (key, desc) in enumerate(hints):
            spans += [(' ' + key + ' ', style(0, 6, True)), (desc, style(15))]
            if i + 1 < len(hints):
                spans.append((' ', DEFAULT))
        s.spans(0, self.h - 1, spans, max(0, self.w - len(tag) - 2))
        if tag:
            s.text(self.w - len(tag) - 4, self.h - 1, ' ' + tag + ' ', style(0, 3, True))

    def render_popup(self, s, selected_y, main_h):
        bs = self.current_branches()
        if self.mode == 'normal' and len(bs) > 1:
            w = min(self.w - 4, max(width(b.name) for b in bs) + 6)
            h = min(len(bs) + 2, max(0, main_h - 2))
            x = max(0, self.w - w - 2)
            y = min(selected_y + 1, max(1, main_h - h - 1))
            s.fill(x, y, w, h, style(-1, 0)); s.box(x, y, w, h, 'Branches', 4, 0)
            off = max(0, self.branch_index - (h - 3))
            for i, b in enumerate(bs[off:off + max(0, h - 2)]):
                active = i + off == self.branch_index
                st = style(0, 4, True) if active else style(15, 0)
                s.text(x + 1, y + 1 + i, ('▶ ' if active else '  ') + b.name, st, w - 2)
        if self.mode == 'help':
            x, y, w, h = self.centered(60, 70)
            s.fill(x, y, w, h, style(-1, 0)); s.box(x, y, w, h, 'Help', 6, 0)
            for i, (key, desc) in enumerate(HELP[:max(0, h - 2)]):
                if desc is None:
                    spans = [(key, style(3, 0, True))]
                else:
                    spans = [(key, style(6, 0, True)), (desc, style(15, 0))]
                s.spans(x + 1, y + 1 + i, spans, w - 2)
        elif self.mode in ('branch', 'confirm'):
            x, y, w, h = self.centered(50, 20)
            title = 'New Branch Name' if self.mode == 'branch' else 'Confirm'
            color = 6 if self.mode == 'branch' else 3
            s.fill(x, y, w, h, style(-1, 0)); s.box(x, y, w, h, title, color, 0)
            if self.mode == 'branch':
                line = [('  ', style(-1, 0)), (self.input, style(15, 0, underline=True)), ('_', style(6, 0))]
                hint = '  Enter: confirm  Esc: cancel'
            else:
                line = [("  Delete branch '%s'?" % self.pending_delete.name, style(15, 0))]
                hint = '  y: Yes  n: No'
            if h > 3:
                s.spans(x + 1, y + 2, line, w - 2)
            if h > 5:
                s.text(x + 1, y + 4, hint, style(8, 0), w - 2)
        elif self.mode == 'search':
            x = rnd(self.w * .2); w = rnd(self.w * .8) - x
            n = min(10, len(self.search_results)) if self.input else 0
            h = n + 5 if n else 4
            h = min(h, max(0, self.h - 1))
            y = self.h - 1 - h
            s.fill(x, y, w, h, style(-1, 0)); s.box(x, y, w, h, 'Search branches', 6, 0)
            if h > 2:
                s.spans(x + 1, y + 1, [('  ', style(-1, 0)), (self.input, style(15, 0, underline=True)), ('_', style(6, 0))], w - 2)
            if n:
                s.text(x + 1, y + 2, '─' * max(0, w - 2), style(8, 0))
                if self.search_choice < self.search_offset:
                    self.search_offset = self.search_choice
                elif self.search_choice >= self.search_offset + n:
                    self.search_offset = self.search_choice - n + 1
                for i, result in enumerate(self.search_results[self.search_offset:self.search_offset + n]):
                    active = i + self.search_offset == self.search_choice
                    name = result[3].name
                    parts = [('▶ ' if active else '  ', style(6 if active else 8, 0))]
                    if active:
                        parts.append((name, style(0, 6, True)))
                    else:
                        parts += [(c, style(3, 0, True) if j in result[4] else style(15, 0)) for j, c in enumerate(name)]
                    if y + 3 + i < y + h - 1:
                        s.spans(x + 1, y + 3 + i, parts, w - 2)
                s.text(x + 1, y + h - 2, '  ↑↓: select  Enter: jump  Esc: cancel', style(8, 0), w - 2)
            elif h > 2:
                hint = '  No matches' if self.input else '  Enter: confirm  Esc: cancel'
                s.text(x + 1, y + h - 2, hint, style(8, 0), w - 2)

    def render(self, w, h):
        self.w, self.h = w, h
        s = Screen(w, h)
        available = max(0, h - 1)
        main_h = rnd(available * .7)
        bottom_h = available - main_h
        selected_y = self.render_list(s, main_h)
        if w >= 57:
            left = rnd(w / 2)
            self.render_detail(s, 0, main_h, left, bottom_h)
            self.render_files(s, left, main_h, w - left, bottom_h)
        else:
            first = rnd(bottom_h / 2)
            self.render_detail(s, 0, main_h, w, first)
            self.render_files(s, 0, main_h + first, w, bottom_h - first)
        self.render_footer(s)
        self.render_popup(s, selected_y, main_h)
        return s

    def tick(self):
        now = time.monotonic()
        changed = False
        if self.fetch_result is not None:
            p, manual = self.fetch_result
            self.fetch_result = None
            self.fetching = False
            if p.returncode and manual:
                self.fail('git fetch failed: ' + p.stderr.decode(errors='replace').strip())
            elif p.returncode == 0:
                self.refresh()
            changed = True
        if self.config['auto_refresh'] and now - self.last_refresh >= self.config['refresh_interval']:
            self.refresh(); changed = True
        if self.config['auto_fetch'] and now - self.last_fetch >= self.config['fetch_interval']:
            self.fetch(False); changed = True
        return changed


ESCAPES = {
    '\x1b[A': 'up', '\x1b[B': 'down', '\x1b[C': 'right', '\x1b[D': 'left',
    '\x1bOA': 'up', '\x1bOB': 'down', '\x1bOC': 'right', '\x1bOD': 'left',
    '\x1b[H': 'home', '\x1b[F': 'end', '\x1bOH': 'home', '\x1bOF': 'end',
    '\x1b[1~': 'home', '\x1b[4~': 'end', '\x1b[7~': 'home', '\x1b[8~': 'end',
    '\x1b[Z': 'backtab', '\x1b[5~': 'pageup', '\x1b[6~': 'pagedown', '\x1b[3~': 'delete',
}
CONTROLS = {'\r': 'enter', '\n': 'ctrl-j', '\t': 'tab', '\x7f': 'backspace', '\b': 'backspace',
            '\x04': 'ctrl-d', '\x15': 'ctrl-u', '\x0b': 'ctrl-k', '\x03': 'ctrl-c'}


def parse_keys(data):
    keys = []
    i = 0
    while i < len(data):
        c = data[i]
        if c == '\x1b':
            found = False
            for seq in sorted(ESCAPES, key=len, reverse=True):
                if data.startswith(seq, i):
                    keys.append(ESCAPES[seq]); i += len(seq); found = True; break
            if found:
                continue
            if i + 1 < len(data):
                if data[i + 1] in '[O':
                    m = re.match(r'\x1b(?:\[[0-9;<:?]*[A-Za-z~]|O.)', data[i:])
                    if m:
                        i += len(m.group()); continue
                keys.append('alt-' + data[i + 1]); i += 2; continue
            keys.append('esc')
        else:
            keys.append(CONTROLS.get(c, c))
        i += 1
    return keys


def cli():
    name = os.path.basename(sys.argv[0]) or 'executable'
    args = sys.argv[1:]
    after = False
    for arg in args:
        if not after and arg == '--':
            after = True; continue
        if not after and arg.startswith('--'):
            if arg in ('--help', '--version'):
                action = arg
            elif arg.startswith('--help=') or arg.startswith('--version='):
                option, value = arg.split('=', 1)
                sys.stderr.write("error: unexpected value '%s' for '%s' found; no more were expected\n\nUsage: %s %s\n\nFor more information, try '--help'.\n" % (value, option, name, option))
                return 2
            else:
                action = ''
        elif not after and arg.startswith('-') and len(arg) > 1:
            first = arg[1]
            action = '--help' if first == 'h' else '--version' if first == 'V' else ''
            if not action:
                arg = '-' + first
        else:
            action = ''
        if action == '--help':
            print('A TUI tool to visualize Git commit graphs with branch genealogy\n\nUsage: %s\n\nOptions:\n  -h, --help     Print help\n  -V, --version  Print version' % name)
            return 0
        if action == '--version':
            print('keifu 0.2.3')
            return 0
        tip = ''
        usage = name
        if arg in ('--hepl', '--hlep', '--hel', '--hep', '--hellp', '--verison', '--versio', '--versions'):
            close = '--version' if arg.startswith('--ver') else '--help'
            tip = "  tip: a similar argument exists: '%s'\n\n" % close
            usage += ' ' + close
        sys.stderr.write("error: unexpected argument '%s' found\n\n%sUsage: %s\n\nFor more information, try '--help'.\n" % (arg, tip, usage))
        return 2
    return None


def main():
    result = cli()
    if result is not None:
        return result
    try:
        repo = Repository()
    except ValueError:
        sys.stderr.write("Error: Git repository not found. Please run inside a Git repository.\n\nCaused by:\n    could not find repository at '.'; class=Repository (6); code=NotFound (-3)\n")
        return 1
    try:
        fd = os.open('/dev/tty', os.O_RDWR)
        old = termios.tcgetattr(fd)
    except OSError as e:
        sys.stderr.write('Error: %s (os error %d)\n' % (e.strerror, e.errno))
        return 1
    app = App(repo)
    dirty = True
    last_size = None
    previous_frame = None
    try:
        tty.setraw(fd)
        os.write(1, b'\x1b[?1049h\x1b[?25l')
        while not app.quit:
            try:
                size = os.get_terminal_size(fd)
                dims = (max(1, size.columns), max(1, size.lines))
            except OSError:
                dims = (80, 24)
            if dims != last_size:
                last_size = dims; dirty = True
            if app.tick():
                dirty = True
            if dirty:
                frame = app.render(*dims).output()
                if frame != previous_frame:
                    os.write(1, frame.encode('utf-8', errors='replace'))
                    previous_frame = frame
                dirty = False
            rd, _, _ = select.select([fd], [], [], .08)
            if rd:
                data = os.read(fd, 65536)
                if not data:
                    break
                if b'\x1b' in data:
                    more, _, _ = select.select([fd], [], [], .025)
                    if more:
                        data += os.read(fd, 65536)
                for key in parse_keys(data.decode('utf-8', errors='replace')):
                    app.key(key)
                    dirty = True
                    if app.quit:
                        break
    except (KeyboardInterrupt, EOFError):
        pass
    finally:
        termios.tcsetattr(fd, termios.TCSADRAIN, old)
        os.write(1, b'\x1b[0m\x1b[?25h\x1b[?1049l')
        os.close(fd)
    return 0


if __name__ == '__main__':
    sys.exit(main())
