def key(k):
 for name in ('fresh','candidate'):run('send-keys','-t',name+':0.0',k)
 time.sleep(.17)
def check(label):
 a=run('capture-pane','-pt','fresh:0.0').splitlines();b=run('capture-pane','-pt','candidate:0.0').splitlines()
 diff=[i for i,(x,y) in enumerate(zip(a,b)) if x!=y]
 if diff:
  print(label, 'DIFFERENT ROWS',diff)
  for i in diff[:3]:print('old:',a[i]);print('new:',b[i])
 return not diff
fixtures=['/tmp/keifu-observe','/tmp/keifu-graph','/tmp/keifu-cross','/tmp/keifu-special','/tmp/keifu-files','/tmp/keifu-root-ties','/tmp/keifu-dirty-old/repo','/tmp/keifu-dropdown/repo']
good=total=0
for p in fixtures:
 for name in ('fresh','candidate'):
  subprocess.run(['tmux','kill-session','-t',name],stderr=subprocess.DEVNULL)
 for name,cmd in [('fresh','executable'),('candidate','keifu.py')]:
  run('new-session','-d','-s',name,'-x','100','-y','36',f'cd {p} && XDG_CONFIG_HOME=/tmp/keifu-settings /workspace/{cmd}; exec bash')
 time.sleep(.4)
 for label,k in [('start',None),('down','j'),('right','l'),('left','h'),('top','g'),('nextbranch',']'),('previous','['),('end','G'),('up','k'),('help','?'),('closehelp','q'),('create','b'),('cancel','Escape'),('search','/'),('query','a'),('searchup','Up'),('searchdown','Down'),('cancel','Escape'),('head','@')]:
  if k:key(k)
  good += check(p+' '+label);total+=1
